<script>
window.addEventListener('load',()=>{if(!window.Chart)return;Chart.defaults.font.family='Inter';Chart.defaults.color='#667085';
const common={responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{usePointStyle:true,boxWidth:8}}},scales:{x:{grid:{display:false}},y:{grid:{color:'#eef1f4'},beginAtZero:true}}};
new Chart(document.getElementById('invoiceChart'),{type:'bar',data:{labels:<?= json_encode(array_column($invoiceTrend,'label')) ?>,datasets:[{label:'Invoiced',data:<?= json_encode(array_map('floatval',array_column($invoiceTrend,'invoiced'))) ?>,backgroundColor:'#344054',borderRadius:2},{label:'Received',data:<?= json_encode(array_map('floatval',array_column($invoiceTrend,'received'))) ?>,backgroundColor:'#0B6F7D',borderRadius:2}]},options:common});
new Chart(document.getElementById('leadChart'),{type:'doughnut',data:{labels:<?= json_encode(array_column($leadStages,'label')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($leadStages,'value'))) ?>,backgroundColor:['#245B8F','#0B6F7D','#526071','#7B8798','#9A6700','#157347','#B42318','#A3ACB9']}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7}}}}});
new Chart(document.getElementById('projectChart'),{type:'doughnut',data:{labels:<?= json_encode(array_column($projectStatuses,'label')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($projectStatuses,'value'))) ?>,backgroundColor:['#245B8F','#0B6F7D','#526071','#9A6700','#157347','#B42318']}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7}}}}});});
</script>
